# A09 companion: build the markdown summary from A09.json (run after A09_smoothed_hazards_muhaz.R)
import json
import config
R = config.RES
j = json.load(open(R + "A09.json")); G = j["groups"]
LAB = {"NEC": "Colorectal NEC", "SCLC": "SCLC", "AC": "Colorectal AC", "PANC": "Pancreatic AC"}
BWL = {"auto": "automatic", "bw0.5": "0.5", "bw1.0": "1.0", "bw1.5": "1.5", "half": "half automatic", "double": "double automatic"}
f = lambda x, d=3: "NA" if x is None else f"{x:.{d}f}"
L = []
L.append("# A09. Kernel-smoothed cause-specific hazard of cancer death (muhaz), distant stage\n")
L.append(f"Script: `R/A09_smoothed_hazards_muhaz.R` (+ `python/A09_write_md.py`). muhaz {j['muhaz_version']}, {j['R_version']}. Runtime {j['runtime_minutes']:.2f} min. Grid CSV: `results/A09_hazard_grid.csv` (97 points, 0-24 months, step 0.25; columns group, bw_label, bandwidth, month, hazard, n_at_risk, and lower95/upper95 for NEC). Convention: n_at_risk = number of patients with tm > s, i.e. strictly surviving past the grid month s (the landmark convention used elsewhere in the toolkit; the authors' T02 script uses tm >= s, which differs only at tied grid points).\n")
L.append("Method: " + j["method"] + ". Bandwidth selection as in the authors' T02 script: pilot = 24/(8*deaths^0.2), 25-point grid 0.2-20 x pilot, grid doubled if the minimum-IMSE optimum fell on the upper edge (never needed). NEC bootstrap: " + j["bootstrap"]["resampling"] + f", B = {j['bootstrap']['B']}, seed {j['bootstrap']['seed']}, " + j["bootstrap"]["ci"] + ".\n")
L.append("## Reproduction check (ours vs manuscript, automatic bandwidth)\n")
L.append("| Item | Manuscript | Ours | Tolerance | OK |\n|---|---|---|---|---|")
for r in j["reproduction_check"]:
    L.append(f"| {r['item']} | {r['manuscript']} | {r['ours']:.4f} | {r['tol']} | {'yes' if r['ok'] else 'NO'} |")
L.append("\nAll 18 anchors reproduce; the script halts if any fails. The six interval-mean anchors (NEC, AC, PANC at 3-6 and 6-9 months) use the authors' trapezoid-rule definition (np.trapz(h, month)/(hi-lo) over the grid points in [lo, hi]); see Revision after second audit.\n")
L.append("## Table 1. Cohorts and automatic bandwidths\n")
L.append("| Tumour | n (distant) | Cancer deaths <=24 mo | Other-cause deaths <=24 mo | Pilot bw (mo) | Automatic bw (mo) | Grid index of optimum |\n|---|---|---|---|---|---|---|")
for g in G: v = G[g]; L.append(f"| {LAB[g]} | {v['n']} | {v['cancer_deaths_24m']} | {v['other_deaths_24m']} | {v['pilot']:.3f} | {v['bw_auto']:.3f} | {v['bw_grid_index']}/25 |")
L.append("\n## Table 2. Trough and peak of the smoothed hazard by tumour and bandwidth\n")
L.append("Primary definition (authors' reading): trough = minimum over months (1, 12]; peak = maximum over (trough, 24]; 'interior' = trough strictly below both neighbouring grid points. Secondary (strict): first local minimum after month 1 and the first local maximum after it. Ratios are hazard ratios (peak / trough). NEC rows carry bootstrap 95% percentile intervals (B = 500). Month intervals use type-1 quantiles, so the limits are attainable 0.25-month grid values. The ratio interval in this table is the *re-optimised* one (trough and peak re-located in every resample): it is a sup/inf statistic whose bootstrap distribution is shifted upward relative to the point estimate (winner's curse) and is reported for completeness only; inference uses the fixed-location and window-mean ratios in Table 2b. Interval means for 3-6 and 6-9 months are shown as trapezoid / plain: trapezoid = np.trapz(h, month)/(hi-lo) over the 13 grid points with lo <= month <= hi, exactly as the authors' T02_draw_and_report.py (endpoints half-weighted; this is the definition behind the manuscript's 0.095 and 0.137); plain = unweighted mean of the same 13 points (the definition used before the second-audit revision).\n")
L.append("| Tumour | Bandwidth (mo) | Trough month | Trough hazard | Peak month | Peak hazard | Ratio peak/trough (re-optimised CI, descriptive) | Strict local min (month, hazard) | Strict local max (month, hazard) | Mean 3-6 (trapezoid / plain) | Mean 6-9 (trapezoid / plain) |\n|---|---|---|---|---|---|---|---|---|---|---|")
for g in G:
    for nm, c in G[g]["curves"].items():
        b = c.get("boot")
        tm = f"{c['min_month']:.2f}" + (f" ({b['min_month_ci'][0]:.2f}-{b['min_month_ci'][1]:.2f})" if b else "")
        pm = f"{c['max_month']:.2f}" + (f" ({b['max_month_ci'][0]:.2f}-{b['max_month_ci'][1]:.2f})" if b else "")
        rt = f"{c['ratio_max_min']:.2f}" + (f" ({b['ratio_reoptimised_ci'][0]:.2f}-{b['ratio_reoptimised_ci'][1]:.2f})" if b else "")
        L.append(f"| {LAB[g]} | {BWL[nm]} ({c['bandwidth']:.3f}) | {tm} | {f(c['min_haz'],4)} | {pm} | {f(c['max_haz'],4)} | {rt} | {f(c['local_min_month'],2)}, {f(c['local_min_haz'],4)} | {f(c['local_max_month'],2)}, {f(c['local_max_haz'],4)} | {c['mean_3_6']:.4f} / {c['mean_3_6_plain']:.4f} | {c['mean_6_9']:.4f} / {c['mean_6_9_plain']:.4f} |")
L.append("\n## Table 2b. NEC: inferential bootstrap intervals for the trough-to-peak rise (fixed location), by bandwidth\n")
L.append("Fixed-month ratio = h(full-sample peak month) / h(full-sample trough month), both months held fixed across resamples; window ratio = interval mean of h over months 6-9 / interval mean over months 3-6, trapezoid rule (authors' definition; the plain unweighted-grid-mean version is shown alongside for comparison, same resamples). Re-optimised columns show the selection bias of the Table 2 ratio: bootstrap mean/median exceed the point estimate.\n")
L.append("| Bandwidth (mo) | Fixed months (trough, peak) | Fixed-month ratio (95% CI) | Window ratio 6-9/3-6, trapezoid (95% CI) | Window ratio 6-9/3-6, plain mean (95% CI) | Re-optimised ratio: point / boot mean / boot median / 95% CI | Trough month 95% CI | Peak month 95% CI | % trough interior | % trough > 6 mo | % peak >= 20 mo | % peak at 24 mo |\n|---|---|---|---|---|---|---|---|---|---|---|---|")
for nm, c in G["NEC"]["curves"].items():
    b = c["boot"]; fm = b["fixed_months"]
    L.append(f"| {BWL[nm]} ({c['bandwidth']:.3f}) | {fm['trough']:.2f}, {fm['peak']:.2f} | {c['ratio_max_min']:.2f} ({b['ratio_fixed_ci'][0]:.2f}-{b['ratio_fixed_ci'][1]:.2f}) | {c['ratio_window']:.2f} ({b['ratio_window_ci'][0]:.2f}-{b['ratio_window_ci'][1]:.2f}) | {c['ratio_window_plain']:.2f} ({b['ratio_window_plain_ci'][0]:.2f}-{b['ratio_window_plain_ci'][1]:.2f}) | {c['ratio_max_min']:.2f} / {b['ratio_reoptimised_boot_mean']:.2f} / {b['ratio_reoptimised_boot_median']:.2f} / {b['ratio_reoptimised_ci'][0]:.2f}-{b['ratio_reoptimised_ci'][1]:.2f} | {b['min_month_ci'][0]:.2f}-{b['min_month_ci'][1]:.2f} | {b['max_month_ci'][0]:.2f}-{b['max_month_ci'][1]:.2f} | {100*b['prop_trough_interior']:.1f} | {100*b['prop_trough_after_6']:.1f} | {100*b['prop_peak_ge_20']:.1f} | {100*b['prop_peak_at_24']:.1f} |")
L.append("\n## Table 3. Smoothed hazard (cancer deaths per person-month) at months 1-24\n")
L.append("| Tumour | Bandwidth | " + " | ".join(f"m{m}" for m in range(1, 25)) + " |\n|---|---|" + "---|" * 24)
for g in G:
    for nm, c in G[g]["curves"].items():
        L.append(f"| {LAB[g]} | {BWL[nm]} ({c['bandwidth']:.2f}) | " + " | ".join(f"{c['h_month'][f'm{m}']:.3f}" for m in range(1, 25)) + " |")
n = G["NEC"]["curves"]
L.append(f"""
## Figures

- `figures/output/A09_panel_bw1.5.png`: four tumours at a common bandwidth of 1.5 months, NEC with pointwise bootstrap 95% band.
- `figures/output/A09_NEC_bandwidths.png`: distant NEC at half ({n['half']['bandwidth']:.2f}), automatic ({n['auto']['bandwidth']:.2f}) and double ({n['double']['bandwidth']:.2f}) bandwidth, band at the automatic bandwidth. The 1.0- and 1.5-month curves are tabulated above; the 1.5-month curve is visually indistinguishable from the automatic one.

## Interpretation

1. The authors' automatic bandwidths and the NEC trough/peak reproduce exactly (NEC 1.484, SCLC 0.336, AC 0.319, PANC 0.335 months; NEC trough at month 4.00 = {n['auto']['min_haz']:.4f}, peak at 8.75 = {n['auto']['max_haz']:.4f}; SCLC trough 4.25 = {G['SCLC']['curves']['auto']['min_haz']:.4f}, peak 10.0 = {G['SCLC']['curves']['auto']['max_haz']:.4f}).
2. The manuscript's "peak" is the maximum after the trough, not the first strict local maximum: at the automatic bandwidth the NEC curve has a small shoulder at 7.5 months ({n['auto']['local_max_haz']:.4f}) before the maximum at 8.75; we recommend defining the peak explicitly as the post-trough maximum within 24 months in the Methods.
3. The bandwidth confound raised by reviewers is real but immaterial for NEC vs SCLC: at a common 1.5-month bandwidth NEC still shows a trough at month 4 ({n['bw1.5']['min_haz']:.4f}) and a second peak at 8.75 ({n['bw1.5']['max_haz']:.4f}; fixed-month ratio {n['bw1.5']['ratio_max_min']:.2f}, bootstrap 95% CI {n['bw1.5']['boot']['ratio_fixed_ci'][0]:.2f}-{n['bw1.5']['boot']['ratio_fixed_ci'][1]:.2f}; window ratio 6-9/3-6 (trapezoid) = {n['bw1.5']['ratio_window']:.2f}, {n['bw1.5']['boot']['ratio_window_ci'][0]:.2f}-{n['bw1.5']['boot']['ratio_window_ci'][1]:.2f}), and SCLC a trough at 4.25 ({G['SCLC']['curves']['bw1.5']['min_haz']:.4f}) and peak at 10.5 ({G['SCLC']['curves']['bw1.5']['max_haz']:.4f}; ratio {G['SCLC']['curves']['bw1.5']['ratio_max_min']:.2f}). SCLC's shape is essentially invariant to bandwidth between 0.34 and 1.5 months because of its 64,373 events.
4. Colorectal and pancreatic adenocarcinoma show no trough-peak cycle at any bandwidth: the post-month-1 minimum lies at 8-11 months and the subsequent "maximum" is 2-15% higher (AC ratio {G['AC']['curves']['bw1.5']['ratio_max_min']:.2f}, PANC {G['PANC']['curves']['bw1.5']['ratio_max_min']:.2f} at 1.5 months), i.e. a flat or monotone-declining hazard. The strict local-extremum columns for these two tumours pick up 0.25-month noise and should not be read as a cycle.
5. Magnitude of the rise, NEC, automatic bandwidth: h(8.75)/h(4.0) = {n['auto']['ratio_max_min']:.2f} (fixed-month bootstrap 95% CI {n['auto']['boot']['ratio_fixed_ci'][0]:.2f}-{n['auto']['boot']['ratio_fixed_ci'][1]:.2f}); trapezoid interval mean h(6-9) / h(3-6) = {n['auto']['mean_6_9']:.4f}/{n['auto']['mean_3_6']:.4f} = {n['auto']['ratio_window']:.2f} ({n['auto']['boot']['ratio_window_ci'][0]:.2f}-{n['auto']['boot']['ratio_window_ci'][1]:.2f}; plain-mean version {n['auto']['ratio_window_plain']:.2f}, {n['auto']['boot']['ratio_window_plain_ci'][0]:.2f}-{n['auto']['boot']['ratio_window_plain_ci'][1]:.2f}). These are the inferential intervals. The interval obtained by re-locating the trough and peak in every resample ({n['auto']['boot']['ratio_reoptimised_ci'][0]:.2f}-{n['auto']['boot']['ratio_reoptimised_ci'][1]:.2f}; bootstrap mean {n['auto']['boot']['ratio_reoptimised_boot_mean']:.2f}, median {n['auto']['boot']['ratio_reoptimised_boot_median']:.2f} vs point {n['auto']['ratio_max_min']:.2f}) is a sup/inf statistic shifted upward by selection and should not be quoted as a confidence interval. The ratio is bandwidth-dependent in magnitude: fixed-month {n['half']['ratio_max_min']:.2f} ({n['half']['boot']['ratio_fixed_ci'][0]:.2f}-{n['half']['boot']['ratio_fixed_ci'][1]:.2f}) at half bandwidth ({n['half']['bandwidth']:.2f} mo), {n['bw1.0']['ratio_max_min']:.2f} ({n['bw1.0']['boot']['ratio_fixed_ci'][0]:.2f}-{n['bw1.0']['boot']['ratio_fixed_ci'][1]:.2f}) at 1.0, {n['double']['ratio_max_min']:.2f} ({n['double']['boot']['ratio_fixed_ci'][0]:.2f}-{n['double']['boot']['ratio_fixed_ci'][1]:.2f}) at double bandwidth ({n['double']['bandwidth']:.2f} mo); the window ratio is less bandwidth-sensitive ({n['half']['ratio_window']:.2f}, {n['auto']['ratio_window']:.2f}, {n['double']['ratio_window']:.2f} at half/auto/double) and its lower limit stays above 1 at every bandwidth, which is the appropriate statement of the rise after month 4.
6. Timing is poorly identified by the bootstrap: the NEC trough-month 95% interval is {n['auto']['boot']['min_month_ci'][0]:.1f}-{n['auto']['boot']['min_month_ci'][1]:.1f} months and the peak-month interval {n['auto']['boot']['max_month_ci'][0]:.2f}-{n['auto']['boot']['max_month_ci'][1]:.2f} months (type-1 quantiles, grid-attainable). The post-trough maximum sits exactly at the 24-month boundary in {100*n['auto']['boot']['prop_peak_at_24']:.1f}% of resamples and at >= 20 months in {100*n['auto']['boot']['prop_peak_ge_20']:.1f}%; the trough is located after month 6 in {100*n['auto']['boot']['prop_trough_after_6']:.1f}%. The manuscript's statement that trough/peak months are descriptive only is appropriate; the 6-9 vs 3-6 month contrast ({n['auto']['mean_6_9']:.3f} vs {n['auto']['mean_3_6']:.3f} per person-month at the automatic bandwidth, trapezoid rule) is the quantity that should carry inference.
7. Pointwise CIs widen from month 16 onward (n at risk < 100: 98 at month 16, 63 at month 20, 48 at month 24) and the boundary estimate at 24 months is unreliable; the authors' practice of not interpreting months 0 and 24 should be stated for both ends.

## Deviations from plan

- Peak defined as the post-trough maximum (authors' convention) rather than the first strict local maximum; both are reported.
- NEC bootstrap used B = 500 as specified (manuscript: 2,000); CIs are percentile and pointwise. No bootstrap for SCLC/AC/PANC (not requested).
- The NEC three-bandwidth figure shows half/automatic/double rather than 1.0/1.48/1.5, because 1.5 and 1.48 overlap; 1.0 and 1.5 appear in the tables and CSV.
- The ratio interval in Table 2 (re-optimised) is retained for completeness but labelled descriptive; inference uses the fixed-month and window-mean ratios of Table 2b, which were not in the original plan.

## Revision after audit

- Added fixed-location bootstrap intervals to the NEC bootstrap block: h(full-sample peak month)/h(full-sample trough month) (`ratio_fixed_ci`) and mean h(6-9)/mean h(3-6) (`ratio_window_ci`), per bandwidth; the former re-optimised ratio interval is renamed `ratio_reoptimised_ci`, its bootstrap mean/median are stored to document the upward selection bias, and the text now quotes the fixed-month / window ratios as the inferential intervals. The sentence that the CI "touches 1" at double bandwidth was removed.
- Trough/peak month bootstrap intervals now use type-1 quantiles (grid-attainable 0.25-month values) and the convention is stated in the Table 2 note.
- Added `prop_peak_at_24`, `prop_peak_ge_20` and `prop_trough_after_6` to the JSON and quoted them in interpretation 6.
- Interpretation 7 corrected: n at risk falls below 100 from month 16 (not 20).
- Grid CSV description now states the n_at_risk convention (tm > s).
- All point estimates, bandwidths, curves, figures and the 18-item reproduction check are unchanged (same seed and resamples).

## Revision after second audit

- Finding: the 3-6 and 6-9 month "mean smoothed hazard" anchors were plain means of the 13 grid points in [3, 6] / [6, 9], whereas the authors' `T02_draw_and_report.py` computes `np.trapz(hazard, month)/(hi-lo)` over the same points, a trapezoid-rule average that half-weights the two endpoints. Fix: `features()` now computes the interval means with the trapezoid rule exactly as the authors do (`imean()` in the R script; the bootstrap uses the equivalent weight vector `tz_weights()`, checked against `imean()` on the full-sample curve). The plain mean is retained as `mean_3_6_plain` / `mean_6_9_plain` and reported alongside in Table 2.
- Window ratio 6-9/3-6 (`ratio_window`, `ratio_window_ci`) re-derived with the trapezoid definition from the same bootstrap resamples (seed {j['bootstrap']['seed']}, B = {j['bootstrap']['B']}); the plain-mean version is kept as `ratio_window_plain` / `ratio_window_plain_ci`. NEC, automatic bandwidth: mean 3-6 {n['auto']['mean_3_6_plain']:.4f} (plain) -> {n['auto']['mean_3_6']:.4f} (trapezoid); mean 6-9 {n['auto']['mean_6_9_plain']:.4f} -> {n['auto']['mean_6_9']:.4f}; window ratio {n['auto']['ratio_window_plain']:.3f} ({n['auto']['boot']['ratio_window_plain_ci'][0]:.3f}-{n['auto']['boot']['ratio_window_plain_ci'][1]:.3f}) -> {n['auto']['ratio_window']:.3f} ({n['auto']['boot']['ratio_window_ci'][0]:.3f}-{n['auto']['boot']['ratio_window_ci'][1]:.3f}). By bandwidth (trapezoid): half {n['half']['ratio_window']:.2f} ({n['half']['boot']['ratio_window_ci'][0]:.2f}-{n['half']['boot']['ratio_window_ci'][1]:.2f}), 1.0 {n['bw1.0']['ratio_window']:.2f} ({n['bw1.0']['boot']['ratio_window_ci'][0]:.2f}-{n['bw1.0']['boot']['ratio_window_ci'][1]:.2f}), 1.5 {n['bw1.5']['ratio_window']:.2f} ({n['bw1.5']['boot']['ratio_window_ci'][0]:.2f}-{n['bw1.5']['boot']['ratio_window_ci'][1]:.2f}), double {n['double']['ratio_window']:.2f} ({n['double']['boot']['ratio_window_ci'][0]:.2f}-{n['double']['boot']['ratio_window_ci'][1]:.2f}); the lower limit stays above 1 at every bandwidth, as before.
- Reproduction check: the six interval-mean anchors now use the trapezoid definition and match the manuscript more closely (NEC 3-6 {n['auto']['mean_3_6']:.4f} vs 0.095, 6-9 {n['auto']['mean_6_9']:.4f} vs 0.137; AC {G['AC']['curves']['auto']['mean_3_6']:.4f}/{G['AC']['curves']['auto']['mean_6_9']:.4f} vs 0.042/0.035; PANC {G['PANC']['curves']['auto']['mean_3_6']:.4f}/{G['PANC']['curves']['auto']['mean_6_9']:.4f} vs 0.134/0.115); the other 12 anchors (bandwidths NEC 1.484 / SCLC 0.336 / AC 0.319 / PANC 0.335; NEC trough 4.0 = {n['auto']['min_haz']:.4f}, peak 8.75 = {n['auto']['max_haz']:.4f}; SCLC trough/peak) are unchanged. All 18 pass.
- Unchanged: bandwidths, hazard curves, grid CSV (regenerated, identical), figures, trough/peak locations, fixed-month and re-optimised ratio intervals, month intervals and the resample-proportion statistics.
- Downstream documents that quote the previous plain-mean values (results_compendium.md Section 12 and item 10 of the issues list; supplementary_tables.md Table S31) should be updated by their owner to the trapezoid values above: mean h(3-6) = {n['auto']['mean_3_6']:.4f}, mean h(6-9) = {n['auto']['mean_6_9']:.4f}, window ratio {n['auto']['ratio_window']:.2f} ({n['auto']['boot']['ratio_window_ci'][0]:.2f}-{n['auto']['boot']['ratio_window_ci'][1]:.2f}) at the automatic bandwidth.
""")
open(R + "A09.md", "w").write("\n".join(L)); print("wrote A09.md")
